// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        vm.assume(caller != address(c.bank()));
        uint initialPot = 0;
        uint initialBankBalance = address(c.bank()).balance;
        uint initialCallerBalance = caller.balance;
        vm.deal(caller, 10);
        vm.prank(caller);
        c.play{value: 10}();
        uint potAfter = c.pot();
        uint bankBalanceAfter = address(c.bank()).balance;
        bool payoutOccurred = (bankBalanceAfter > initialBankBalance);
        if (payoutOccurred) {
            assertTrue(potAfter == 0);
        } else {
            assertTrue(potAfter == 10);
        }
    }
}

